          const cells = Array.from(root.querySelectorAll('[data-a="cell"]'));
          const gapIdx = [11, 23];
          // column-major sweep order
          const order = [];
          for (let c = 0; c < 5; c++) for (let r = 0; r < 5; r++) order.push(r * 5 + c);
          const mapped = order.filter((i) => gapIdx.indexOf(i) === -1);
          const gapCells = gapIdx.map((i) => cells[i]);
          const num = { pct: 0, docs: 0 };
          const pctEl = one('pct'), docsEl = one('docs');
          const tl = g.timeline({ repeat: -1, defaults: { ease: 'power2.out' } });
          this._compTl = tl;
          mapped.forEach((i, k) => {
            const t = .3 + k * .085;
            tl.to(cells[i].querySelector('[data-a="f"]'), { opacity: 1, duration: .3 }, t)
              .to(cells[i].querySelector('[data-a="k"]'), { opacity: 1, duration: .25 }, t + .1);
          });
          tl.to(num, { pct: 92, duration: 2.2, ease: 'none', onUpdate: () => { pctEl.textContent = Math.round(num.pct) + '%'; } }, .3)
            .to(num, { docs: 42, duration: 2.6, ease: 'power1.out', onUpdate: () => { docsEl.textContent = Math.round(num.docs); } }, 1.1);
          const gapT = 3.1;
          gapCells.forEach((el, k) => {
            tl.fromTo(el.querySelector('[data-a="g"]'), { opacity: 0 }, { opacity: 1, duration: .35, immediateRender: false }, gapT + k * .25)
              .to(el, { scale: 1.14, duration: .3, yoyo: true, repeat: 1 }, gapT + k * .25);
          });
          tl.to(one('title1'), { opacity: 0, duration: .3 }, gapT + .2)
            .to(one('title2'), { opacity: 1, duration: .35 }, gapT + .35);
          const close = 5.6;
          gapCells.forEach((el, k) => {
            const t = close + k * .5;
            tl.to(el.querySelector('[data-a="g"]'), { opacity: 0, duration: .35 }, t)
              .to(el.querySelector('[data-a="f"]'), { opacity: 1, duration: .35 }, t)
              .to(el.querySelector('[data-a="k"]'), { opacity: 1, duration: .3 }, t + .15);
          });
          tl.to(num, { pct: 100, duration: 1.2, ease: 'power2.out', onUpdate: () => { pctEl.textContent = Math.round(num.pct) + '%'; } }, close)
            .to(num, { docs: 47, duration: 1.2, onUpdate: () => { docsEl.textContent = Math.round(num.docs); } }, close)
            .to(one('pill1'), { opacity: 0, duration: .3 }, close + .9)
            .to(one('pill2'), { opacity: 1, duration: .35 }, close + 1)
            .to(one('stat1'), { opacity: 0, duration: .3 }, close + .9)
            .to(one('stat2'), { opacity: 1, duration: .35 }, close + 1)
            .to(one('dot'), { backgroundColor: GREEN, duration: .4 }, close + .9)
            .to(one('title2'), { opacity: 0, duration: .3 }, close + 1.2)
            .to(one('title3'), { opacity: 1, duration: .35 }, close + 1.35);
